		expect(t, "manage-projects-P1", 3, out3, err3, `{"result":"[{\"ProjectID\":\"stp-psa-mp-p1\",\"Name\":\"STP Manage Projects P1\",\"Owner\":\"stp-psa-owner-mp-p1\",\"Phase\":0}]","errorExpected":false}`)
